        self.val = val
        self.left = left
        self.right = right

def isSymmetric(self, root: TreeNode) -> bool:
    def is_mirror(a: TreeNode, b: TreeNode) -> bool:
        if a is None and b is None:   # both empty → mirror
            return True
        if a is None or b is None:    # exactly one empty → not
            return False
        return (a.val == b.val
                and is_mirror(a.left, b.right)    # outer pair
                and is_mirror(a.right, b.left))   # inner pair

    return root is None or is_mirror(root.left, root.right)

